 import React, { useState } from 'react';

 function App() {
   const [name, setName] = useState('');
   const [city, setCity] = useState('');
   const [showGreeting, setShowGreeting] = useState(false);

   // Array of random city compliments
   const cityCompliments = [
     "such a vibrant and amazing place to live!",
     "known for its incredible culture and friendly people!",
     "a truly beautiful city with so much character!",
     "home to some of the most wonderful people!",
     "a place full of history and charm!",
     "such a dynamic and exciting city!",
     "blessed with amazing scenery and atmosphere!",
     "a hidden gem with so much to offer!",
     "where dreams come true and memories are made!",
     "a city that never fails to inspire!",
     "full of energy and endless possibilities!",
     "a perfect blend of tradition and modernity!",
     "where every street tells a unique story!",
     "a wonderful place that anyone would love to call home!",
     "truly one of the most special places on Earth!"
   ];

   const handleSubmit = (e) => {
     e.preventDefault();
     if (name.trim() && city.trim()) {
       setShowGreeting(true);
     }
   };

   return (
     <div className="app-container">
       <div className="form-container">
         <h1>Name Greeting App</h1>

         <form onSubmit={handleSubmit}>
           <div className="input-group">
             <label htmlFor="name">Enter Your Name:</label>
             <input
               type="text"
               id="name"
               value={name}
               onChange={(e) => setName(e.target.value)}
               placeholder="Your name"
             />
           </div>

           <div className="input-group">
             <label htmlFor="city">Enter Your City:</label>
             <input
               type="text"
               id="city"
               value={city}
               onChange={(e) => setCity(e.target.value)}
               placeholder="Your city"
             />
           </div>

           <button type="submit" className="submit-button">
             Submit
           </button>
         </form>

         {showGreeting && (
           <div className="greeting-container">
             <h2>Hello, {name}!</h2>
             <p>We hear {city} is {cityCompliments[Math.floor(Math.random() * cityCompliments.length)]}</p>
           </div>
         )}
       </div>
     </div>
   );
 }

 export default App;

